ORDER_MODEL = """
explore: orders {
  join: users {
    relationship: many_to_one
    sql_on: ${orders.user_id} = ${users.id} ;;
  }
}
"""


DERIVED_VIEW = """
view: order_rollup {
  derived_table: {
    sql:
      SELECT status, SUM(amount) AS total_amount
      FROM public.orders
      GROUP BY status ;;
  }

  dimension: status {
    type: string
    sql: ${TABLE}.status ;;
  }
}
"""


def test_parse_lookml_project_returns_views_and_joins() -> None:
    response = parse_lookml_project(
        ParseLookMLRequest(
            files=[
                LookMLFileInput(path="views/orders.view.lkml", content=ORDER_VIEW),
                LookMLFileInput(path="views/users.view.lkml", content=USER_VIEW),
                LookMLFileInput(
                    path="models/ecommerce.model.lkml", content=ORDER_MODEL
                ),
            ],
            dialect="postgres",
        )
    )

    views = {view.name: view for view in response.views}
    assert sorted(views) == ["orders", "users"]
    assert views["orders"].source_type == "table"
    assert views["orders"].table_ref == "public.orders"
    assert views["orders"].grain == ["id"]
    assert [measure.name for measure in views["orders"].measures] == [
        "order_count",
        "revenue",
    ]
    assert views["orders"].measures[0].expr == "count(*)"
    assert views["orders"].measures[1].expr == "sum(amount)"
    assert response.joins[0].source_view == "orders"
    assert response.joins[0].to == "users"
    assert response.joins[0].relationship == "many_to_one"
    assert response.joins[0].on == "orders.user_id = users.id"
    assert response.skipped_views == []
    assert response.warnings == []


def test_parse_lookml_project_extracts_derived_table_columns() -> None:
    response = parse_lookml_project(
        ParseLookMLRequest(
            files=[
                LookMLFileInput(
                    path="views/order_rollup.view.lkml", content=DERIVED_VIEW
                )
            ],
            dialect="postgres",
        )
    )

    assert len(response.views) == 1
    view = response.views[0]
    assert view.name == "order_rollup"
    assert view.source_type == "sql"
    assert "SELECT status, SUM(amount) AS total_amount" in (view.sql or "")
    assert [column.name for column in view.columns] == ["status", "total_amount"]
    assert response.skipped_views == []
    assert response.warnings == []

from ktx_daemon import PACKAGE_NAME, VERSION, resolve_package_version


def test_package_metadata() -> None:
    assert PACKAGE_NAME == "ktx-daemon"
    assert VERSION == resolve_package_version()


def test_package_version_prefers_bundled_runtime_distribution() -> None:
    calls: list[str] = []

    def fake_version(distribution_name: str) -> str:
        calls.append(distribution_name)
        if distribution_name == "kaelio-ktx":
            return "0.1.0rc1"
        raise AssertionError(f"unexpected distribution lookup: {distribution_name}")

    assert resolve_package_version(version_loader=fake_version) == "0.1.0rc1"
    assert calls == ["kaelio-ktx"]

from __future__ import annotations

from ktx_daemon.sql_analysis import (
    AnalyzeSqlBatchItem,
    AnalyzeSqlBatchRequest,
    ValidateReadOnlySqlRequest,
    _columns_from_nodes,
    analyze_sql_batch_response,
    validate_read_only_sql_response,
)


def test_analyze_sql_batch_extracts_tables_and_clause_columns() -> None:
    response = analyze_sql_batch_response(
        AnalyzeSqlBatchRequest(
            dialect="postgres",
            items=[
                AnalyzeSqlBatchItem(
                    id="orders_by_customer",
                    sql=(
                        "select o.status, count(*) "
                        "from public.orders o "
                        "join public.customers c on o.customer_id = c.id "
                        "where o.created_at >= current_date - interval '30 day' "
                        "group by o.status"
                    ),
                )
            ],
            max_workers=1,
        )
    )

    result = response.results["orders_by_customer"]
    assert result.error is None
    assert [item.model_dump() for item in result.tables_touched] == [
        {"catalog": None, "db": "public", "name": "orders"},
        {"catalog": None, "db": "public", "name": "customers"},
    ]
    assert result.columns_by_clause == {
        "select": ["status"],
        "where": ["created_at"],
        "join": ["customer_id", "id"],
        "groupBy": ["status"],
    }


def test_analyze_sql_batch_returns_per_item_parse_errors() -> None:
    response = analyze_sql_batch_response(
        AnalyzeSqlBatchRequest(
            dialect="postgres",
            items=[AnalyzeSqlBatchItem(id="broken", sql="select * from where")],
            max_workers=1,
        )
    )

    result = response.results["broken"]
    assert result.tables_touched == []
    assert result.columns_by_clause == {}
    assert result.error is not None


